   122	int EVP_PKEY_cmp_parameters(const EVP_PKEY *a, const EVP_PKEY *b)
   123	{
   124	    if (a->type != b->type)
   125	        return -1;
   126	    if (a->ameth && a->ameth->param_cmp)
   127	        return a->ameth->param_cmp(a, b);
   128	    return -2;
